SELECT wr.wr_returned_date_sk, wr.wr_returned_time_sk, td.t_hour, td.t_minute, td.t_second, wr.wr_return_quantity, wr.wr_return_amt, wr.wr_return_tax, wr.wr_return_ship_cost, (td.t_hour * 3600 + td.t_minute * 60 + td.t_second) AS time_in_seconds, (wr.wr_return_amt + wr.wr_return_tax + wr.wr_return_ship_cost) AS total_return_amount, (wr.wr_return_quantity * wr.wr_return_amt) AS total_return_value, CASE WHEN wr.wr_return_amt > 1469.22 THEN 'High' ELSE 'Low' END AS return_amount_category, CASE WHEN td.t_am_pm = 'AM' THEN 'Morning' ELSE 'Evening' END AS time_of_day, CASE WHEN (wr.wr_return_quantity * wr.wr_return_amt) > 197839.84 THEN 'Large' ELSE 'Small' END AS quantity_value_category, (wr.wr_fee - wr.wr_return_ship_cost) AS fee_adjusted FROM web_returns wr INNER JOIN time_dim td ON wr.wr_returned_time_sk = td.t_time_sk WHERE td.t_hour BETWEEN 0 AND 19 AND wr.wr_return_quantity > 31
